with profile_data as (
  select * from jsonb_to_recordset('[{"email": "raza.aima@gmail.com", "brief": "Aima Raza is the founder and president of The Peace Project, a nonprofit that creates supportive, inclusive educational environments and advances human-rights and citizenship education. Her work is centered on community, belonging, and social impact.", "source_url": "https://peaceprojectinc.org/board-of-trustees/"}, {"email": "amna@audeliss.com", "brief": "Amna Khilji is Vice President for North America at Audeliss, where she advises boards and senior leaders on executive search, leadership, and inclusive growth. She brings more than a decade of experience in business development and client relations across multiple sectors and markets.", "source_url": "https://www.audeliss.com/en_us/our-people/"}, {"email": "anjali.virmani@gmail.com", "brief": "Anjali Virmani is Senior Vice President of Business Development at BeautyMatter, a global beauty and wellness intelligence platform. A marketing and business-development leader, she works at the intersection of brand growth, industry partnerships, and the evolving beauty marketplace.", "source_url": "https://www.linkedin.com/in/anjali-virmani-8b0265"}, {"email": "studio@anoushkamirchandani.com", "brief": "Anoushka Mirchandani is an India-born, San Francisco-based artist whose practice explores identity, belonging, concealment, and revelation. Her work has been presented in solo exhibitions at institutions and galleries including The FLAG Art Foundation, ICA San José, Yossi Milo, Galerie Isa, and UTA Artist Space.", "source_url": "https://www.anoushkamirchandani.com/about"}, {"email": "anouska.biswas@gmail.com", "brief": "Anouska Biswas is Director of Finance at the James Beard Foundation. Her work supports the foundation’s financial operations and practical business education for the culinary community, including programs designed to strengthen independent restaurants’ financial management.", "source_url": "https://www.jamesbeard.org/about-us/our-people"}, {"email": "cherylkarim1@gmail.com", "brief": "Cheryl Karim is National Practice Leader and Managing Director of Fine Arts at Gallagher, specializing in insurance and risk strategy for collectors, artists, galleries, and cultural organizations. She was recognized as a 2024 Fine Arts Power Broker by Risk & Insurance.", "source_url": "https://riskandinsurance.com/award-profile/gallagher-broker-cheryl-karim-recognized-as-2024-fine-arts-power-broker/"}, {"email": "kavita.gupta2017@gmail.com", "brief": "Kavita Gupta is the founder and general partner of Delta Blockchain Fund. An investor and entrepreneur focused on blockchain and emerging technologies, she has worked across venture investing, company-building, and the development of the broader digital-asset ecosystem.", "source_url": "https://www.themarque.com/profile/kavita-gupta"}, {"email": "kinjil.mathur@gmail.com", "brief": "Kinjil Mathur is an advisor and board member whose career spans culture and technology. A former Chief Marketing Officer of Squarespace, she is an active arts participant and collector whose work brings together creative thinking, business leadership, and community engagement.", "source_url": "https://events.salute.community/livingwithart/"}, {"email": "madhu.g.southworth@gmail.com", "brief": "Madhu Goel Southworth is a senior legal and business-affairs executive whose career spans sports, media, entertainment, technology, and content monetization. Her leadership experience includes senior roles at Major League Baseball and AMC Networks, with a focus on complex commercial and strategic matters.", "source_url": "https://go.yu.edu/cardozo/fame"}, {"email": "melissa@mjosephstudio.com", "brief": "Melissa Joseph is a New York-based artist known for needle-felted paintings that examine family, history, materiality, place, and diasporic life. Her work is held in permanent collections including the Brooklyn Museum, RISD Museum, ICA Miami, Akron Art Museum, Ruby City, and Flint Institute of Arts.", "source_url": "https://events.salute.community/livingwithart/"}, {"email": "mona@reframewithmona.com", "brief": "Mona Patel is an executive coach and the founder of Reframe with Mona. Her practice helps leaders and teams reconsider entrenched challenges, uncover clearer paths forward, and build the habit of approaching difficult problems from more productive perspectives.", "source_url": "https://www.reframewithmona.com/"}, {"email": "monica.issar@blackstone.com", "brief": "Monica Issar is a Senior Managing Director in Blackstone Multi-Asset Investing and Head of Total Portfolio Management. She brings more than 25 years of experience in multi-asset investing, portfolio solutions, and building investment platforms for institutional and private clients globally.", "source_url": "https://www.blackstone.com/people/monica-issar/"}, {"email": "nehaksingh@gmail.com", "brief": "Neha Singh is Co-Founder of SALUTE and Vice President of Marketing Strategy at J.P. Morgan. At SALUTE, she leads brand-building and develops data-driven growth strategies that support a professional community for South Asian women and allies.", "source_url": "https://www.salute.community/people/neha-singh"}, {"email": "netashajadon@gmail.com", "brief": "Netasha Jadon is a finance leader and a member of the SALUTE team. SALUTE’s published profile identifies her as Director of Finance at LMI and notes prior experience in financial intelligence and related analytical work.", "source_url": "https://www.salute.community/people/netasha-jadon"}, {"email": "nikila.s.srinivasan@gmail.com", "brief": "Nikila Srinivasan is an advisor and investor and a former Meta Vice President and General Manager for Business Messaging and AI. At Meta, she led products connecting people and businesses across WhatsApp, Messenger, and Instagram Direct.", "source_url": "https://www.linkedin.com/in/nikila"}, {"email": "nmphoto101@gmail.com", "brief": "Nivedha Meyyappan is a Partnerships Analyst with the United Nations Spotlight Initiative, which works to end violence against women and girls. She has also contributed photography to projects and programs centered on women, identity, dignity, and social impact.", "source_url": "https://www.linkedin.com/in/nivedha-meyyappan"}, {"email": "rkshah28@gmail.com", "brief": "Rachna Shah is the founder and General Counsel of External General Counsel LLC. Her work provides companies and founders with outside general-counsel leadership and practical guidance across business, legal, and strategic matters.", "source_url": "https://blog.aabany.org/tag/rachna-shah/"}, {"email": "rashmi.gupta@jpmorgan.com", "brief": "Rashmi Gupta is a Managing Director and Portfolio Manager at J.P. Morgan, where she manages global emerging-markets strategies. She brings more than 20 years of capital-markets experience and serves on the board of World Wildlife Fund.", "source_url": "https://www.worldwildlife.org/about/profiles/rashmi-gupta/"}, {"email": "rebecca@the-well.com", "brief": "Rebecca Parekh is Co-Founder and CEO of THE WELL, an integrated wellness company created to make holistic health more accessible and connected. Before founding THE WELL, she worked in finance and later helped build a platform combining wellness services, hospitality, and community.", "source_url": "https://fortune.com/well/2023/08/29/ceo-rebecca-parekh-wellness-habits/"}, {"email": "ispadder@gmail.com", "brief": "Sadaf Padder is a Brooklyn-based independent curator and art advisor whose practice explores migration, ecology, material histories, and cultural memory. She supports artists through exhibitions, writing, teaching, collection-building, and institutional service, with a particular focus on sustained engagement and works by women artists.", "source_url": "https://events.salute.community/livingwithart/"}, {"email": "sana@theramadanedit.com", "brief": "Sana Raheem is the founder of Mubarak & Co., an independent creative platform, and a senior people leader at The Farmer’s Dog. Her work brings together brand-building, culture, community, and the creation of meaningful experiences for Muslim audiences.", "source_url": "https://www.linkedin.com/in/sana-raheem"}, {"email": "bokharisanie@gmail.com", "brief": "Sanié Bokhari is a Lahore-born, Brooklyn-based mixed-media artist whose practice investigates South Asian history, migration, imperialism, motherhood, and life between cultures. She studied painting at the National College of Arts and earned an MFA from the Rhode Island School of Design.", "source_url": "https://www.swivelgallery.com/sanie-bokhari"}, {"email": "sehrthadhani@gmail.com", "brief": "Sehr Thadhani is Chief Digital Officer at Nasdaq, where she develops strategic initiatives across consumer engagement, client experience, market expansion, and brand strategy. Her career includes senior executive and advisory roles at Google, NBC, Viacom, Silicon Foundry, and Edelman Digital.", "source_url": "https://goldhouse.org/people/sehr-thadhani/"}, {"email": "shama85@gmail.com", "brief": "Shama Amin is the founder of Aray Marketing, where she advises organizations on marketing strategy, multicultural audiences, and brand growth. Her career includes senior marketing experience at Bloomberg and Citi.", "source_url": "https://www.linkedin.com/in/shamaamin"}, {"email": "sreddy9@gmail.com", "brief": "Sri Murthy leads global ESG reporting at The Estée Lauder Companies. She also serves on the board of South Asian Youth Action, bringing together experience in corporate sustainability, accountability, and community leadership.", "source_url": "https://www.saya.org/sayaboard"}, {"email": "zainabareejm@gmail.com", "brief": "Zainab Muzaffar is the founder of Impact Play Philanthropy and a fundraising and external-affairs leader. Her work helps athletes, universities, and mission-driven partners develop thoughtful philanthropic strategies, with a focus on community engagement and Muslim audiences.", "source_url": "https://www.impactplayphilanthropy.com/about"}]'::jsonb)
    as x(email text, brief text, source_url text)
), event as (
  select id from public.salute_event_pages where slug='livingwithart'
)
insert into public.salute_living_with_art_guest_briefs (guest_response_id, brief, source_url, updated_at)
select response.id, profile_data.brief, profile_data.source_url, now()
from profile_data
join public.salute_event_responses response on lower(response.email)=profile_data.email
join event on event.id=response.event_id
on conflict (guest_response_id) do update
set brief=excluded.brief, source_url=excluded.source_url, updated_at=excluded.updated_at;
